body.raw:
{
  "userId": "{{userId}}",
  "type": "transactional",
  "category": "order",
  "channels": [
    "email",
    "push"
  ],
  "priority": "normal",
  "subject": "Test notification {{uniqueSuffix}}",
  "body": "This is a test notification from Postman at {{timestamp}}",
  "data": {
    "source": "postman"
  }
}

{
  "to": [
    "test@example.com"
  ],
  "subject": "Test Email {{uniqueSuffix}}",
  "text": "This is a plain text test email sent at {{timestamp}}",
  "html": "<p>Test email at {{timestamp}}</p>",
  "priority": "normal"
}

{
  "name": "Test Template {{uniqueSuffix}}",
  "slug": "test-template-{{uniqueSuffix}}",
  "type": "email",
  "category": "order",
  "locale": "en",
  "subject": "Order {{orderId}} update",
  "body": "Hello {{userName}}, your order {{orderId}} is {{status}}.",
  "variables": [
    {
      "name": "userName",
      "type": "string",
      "required": true
    },
    {
      "name": "orderId",
      "type": "string",
      "required": true
    },
    {
      "name": "status",
      "type": "string",
      "required": true
    }
  ]
}
